const BASE = 'https://api.plugnotas.com.br';
const H = { 'x-api-key': process.env.PLUGNOTAS_API_KEY!, 'Content-Type': 'application/json' };

export async function emitirNfse(documento: unknown) {
  const r = await fetch(`${BASE}/nfse`, { method: 'POST', headers: H, body: JSON.stringify([documento]) });
  const corpo = await r.json();
  if (r.status === 409) {
    // ja existia: reaproveita o documento anterior em vez de emitir de novo
    return { id: corpo.error.data.current.id, duplicado: true };
  }
  if (!r.ok) throw new Error(JSON.stringify(corpo));
  return { id: corpo.documents[0].id, duplicado: false };
}

import os, requests

BASE = 'https://api.plugnotas.com.br'
H = {'x-api-key': os.environ['PLUGNOTAS_API_KEY']}

def notas_do_periodo(cpf_cnpj, data_inicial, data_final):
    registros, cursor = [], None
    while True:
        filtros = {'cpfCnpj': cpf_cnpj, 'dataInicial': data_inicial, 'dataFinal': data_final}
        if cursor:
            filtros['hashProximaPagina'] = cursor
        p = requests.get(f'{BASE}/nfse/consultar/periodo', headers=H, params=filtros, timeout=60).json()
        registros += p.get('notas', [])
        cursor = p.get('hashProximaPagina')
        if not cursor:
            return registros

