import os, requests

BASE = 'https://api.plugnotas.com.br'
H = {'x-api-key': os.environ['PLUGNOTAS_API_KEY']}

def relatorio(rota, de, ate):
    linhas, pagina = [], 1
    while True:
        p = {'from': de, 'to': ate, 'page': pagina, 'perPage': 100}
        corpo = requests.get(f'{BASE}{rota}', headers=H, params=p, timeout=60).json()
        if not corpo:
            break
        rodape = corpo[-1] if isinstance(corpo[-1], dict) and 'totalPages' in corpo[-1] else None
        linhas += corpo[:-1] if rodape else corpo
        if not rodape or pagina >= rodape['totalPages']:
            break
        pagina += 1
    return linhas

for linha in relatorio('/nfse/relatorio', '2026-08-01T00:00:00', '2026-08-31T23:59:59'):
    print(linha['prestador']['cpfCnpj'], linha['documentos'])

