const BASE = 'https://api.plugnotas.com.br';
const H = { 'x-api-key': process.env.PLUGNOTAS_API_KEY! };

export async function baixarXmlNfe(idOuChave: string) {
  const r = await fetch(`${BASE}/nfe/${idOuChave}/xml?tipo=autorizacao`, { headers: H });
  if (r.headers.get('content-type')?.includes('application/json')) {
    const corpo = await r.json();
    return { pronto: false, mensagem: corpo.message }; // HTTP 202: ainda em geracao
  }
  if (!r.ok) throw new Error(`HTTP ${r.status}`);
  return { pronto: true, xml: await r.text() };
}
